import type { Objective } from '@/entities/objective/types'
import { Badge } from './Badge'
import { CheckCircle2, Users } from 'lucide-react'
import { clsx } from 'clsx'

type Props = { objective: Objective; onClick?: () => void }

const STATUS_VARIANT: Record<string, 'default' | 'success' | 'warning' | 'info' | 'outline'> = {
  in_progress: 'info',
  assigned: 'default',
  completed: 'success',
  under_evaluation: 'warning',
  draft: 'outline',
  open: 'outline',
  cancelled: 'outline',
}

const STATUS_ACCENT: Record<string, string> = {
  in_progress: 'border-l-accent-yellow',
  assigned: 'border-l-accent-yellow',
  completed: 'border-l-accent-green',
  under_evaluation: 'border-l-accent-yellow',
  draft: 'border-l-border',
  open: 'border-l-accent-yellow',
  cancelled: 'border-l-border',
}

export function ObjectiveCard({ objective, onClick }: Props) {
  const progress = objective.tasksCount > 0
    ? Math.round((objective.completedTasksCount / objective.tasksCount) * 100)
    : 0

  const accentClass = STATUS_ACCENT[objective.status] ?? 'border-l-border'

  return (
    <button
      onClick={onClick}
      className={clsx(
        'w-full text-left bg-surface rounded-lg border border-border border-l-4 p-4',
        'hover:shadow-card transition-shadow',
        accentClass,
      )}
    >
      <div className="flex items-start justify-between mb-2">
        <h3 className="font-medium text-sm flex-1 pr-3 text-foreground">{objective.title}</h3>
        <Badge variant={STATUS_VARIANT[objective.status] ?? 'outline'}>
          {objective.status.replace('_', ' ')}
        </Badge>
      </div>

      {objective.description && (
        <p className="text-xs text-muted-foreground line-clamp-1 mb-3">{objective.description}</p>
      )}

      <div className="flex items-center gap-4 text-xs text-muted-foreground">
        <span className="flex items-center gap-1">
          <CheckCircle2 size={11} /> {objective.completedTasksCount}/{objective.tasksCount} tasks
        </span>
        <span className="flex items-center gap-1">
          <Users size={11} /> {objective.participants.length}
        </span>
        {objective.assignedValue && (
          <span className="text-primary font-medium">${objective.assignedValue.toLocaleString()}</span>
        )}
      </div>

      {objective.tasksCount > 0 && (
        <div className="mt-3 h-1.5 bg-muted rounded-progress overflow-hidden">
          <div className="h-full bg-primary rounded-progress" style={{ width: `${progress}%` }} />
        </div>
      )}
    </button>
  )
}
